  [587] = { "マフィンを$N1個創造し、メイジとその仲間に食べ物を用意します。\n\nログアウトしてから15分以上経つと、創造されたアイテムは消えます。", nil, 0x5bc23409, nil, "um" },
  [588] = { "Holyのエネルギーが術者を満たし、アーマーを$N1増加させます。プリーストが近接攻撃または遠隔攻撃のダメージを受けるたびに、チャージを1回消費します。効果時間は$D1、または$N3回のチャージを使い切るまでです。", "アーマーが$N1増加します。", 0x92b16b08, 0xa12ba50b, "uu" },
  [589] = { "闇の言葉で、$D1かけて$N1のShadowダメージを与えます。", "$N2秒ごとに$N1のShadowダメージを受けます。", 0x2558a1e5, 0x9554e839, "uu" },
  [591] = { "敵を打ち据え、$N1のHolyダメージを与えます。", nil, 0x05e38ce8, nil, "um" },
  [592] = { "パーティメンバーの魂の力を引き出して盾で守り、$N1のダメージを吸収します。効果時間は$D1です。盾が持続している間は、ダメージを受けても呪文の詠唱が中断されません。一度盾で守られた対象は、$D2の間、再び盾で守ることができません。", "ダメージを$N1吸収します。", 0xec6b3c65, 0x4e7b6db5, "uu" },
  [594] = { "$D1かけて$N1のShadowダメージを与える闇の言葉です。", "$N2秒ごとに$N1のShadowダメージを受けます。", 0x2558a1e5, 0x9554e839, "uu" },
  [596] = { "対象とそのパーティのメンバーを\n$N1回復する強力な祈りです。\nパーティメンバーは対象から$N2ヤード以内にいる必要があります。", nil, 0xacda4668, nil, "um" },
  [597] = { "パンを$N1個創造し、メイジとその仲間に食べ物を用意します。\n\nログアウトしてから15分以上経つと、創造されたアイテムは消えます。", nil, 0x2ada687e, nil, "um" },
  [598] = { "敵を打ち据え、$N1のHolyダメージを与えます。", nil, 0x05e38ce8, nil, "um" },
  [600] = { "パーティメンバーの魂の力を引き出して盾で守り、$N1のダメージを吸収します。効果時間は$D1です。盾が持続している間は、ダメージを受けても呪文の詠唱が中断されません。一度盾で守られた対象は、$D2の間、再び盾で守ることができません。", "ダメージを$N1吸収します。", 0xec6b3c65, 0x4e7b6db5, "uu" },
  [602] = { "Holyのエネルギーが術者を満たし、アーマーを$N1増加させます。プリーストが近接攻撃または遠隔攻撃のダメージを受けるたびに、チャージを1回消費します。効果時間は$D1、または$N3回のチャージを使い切るまでです。", "アーマーが$N1増加します。", 0x92b16b08, 0xa12ba50b, "uu" },
  [603] = { "対象に迫り来る破滅をもたらし、$D1後に$N1のShadowダメージを与えます。このダメージで対象が死亡すると、一定の確率でDoomguardが召喚されます。プレイヤーには使用できません。1体の対象に対して、各ウォーロックがかけられるBaneは1つだけです。", "$D1後に$N1のShadowダメージを受けます。", 0xe932f243, 0xa9e12dea, "uu" },
  [604] = { "対象のパーティメンバーに向けられた魔法を弱め、呪文から受けるダメージを最大$N1、回復呪文の効果を最大$N2減少させます。効果時間は$D1です。", "受ける魔法ダメージが最大$N1、受ける治療効果が最大$N2減少します。", 0x7874f2a2, 0x77e92ccc, "uu" },
  [605] = { "レベル$N1までの人型生物の精神を支配しますが、その攻撃間隔が$N2%長くなります。最大$D1持続します。", "魅了されています。攻撃の間隔が$N1%増加しています。", 0x8506274c, 0xd1990300, "uu" },
  [606] = { "$D1かけて対象からマナを$N1吸い取ります。", "5秒ごとにマナを$N1ポイント吸い取られています。", 0x0e1b3946, 0xae83703e, "uu" },
  [614] = { "Shadow Word: Fumble（Rank 1）を習得します。", nil, 0xdd2f34a6, nil, "um" },
  [626] = { "Seal of Might（Rank 3）を習得します。", nil, 0x61a29bf7, nil, "um" },
  [633] = { "味方ターゲットの体力をパラディンの最大体力\nまで回復します。\n\n使用時にパラディンの残りのマナを\nすべて消費しますが、マナの回復は中断されません。", nil, 0x8b7a4a5b, nil, "um" },
  [635] = { "味方の対象を$N1回復します。", nil, 0xbe4c0f4a, nil, "um" },
  [639] = { "味方の対象を$N1回復します。", nil, 0xbe4c0f4a, nil, "um" },
  [642] = { "$D1の間、パラディンをすべてのダメージと呪文から守りますが、与えるダメージがすべて$N2%減少します。$D2の間Forbearanceを付与します。Forbearanceが有効な間は詠唱できません。", "すべての攻撃と呪文が効きませんが、与えるすべてのダメージが$N1%減少します。", 0x0bcdb662, 0x69b0b050, "uu" },
  [643] = { "$N2ヤード以内のパーティーメンバーのアーマーを$N1増加させます。各プレイヤーにかけられるAuraは、パラディンごとに一度に一つだけです。", "アーマーが$N1増加します。", 0xc600442a, 0xa12a98e7, "uu" },
  [647] = { "味方の対象を$N1回復します。", nil, 0xbe4c0f4a, nil, "um" },
  [650] = { "Blood Boil（Rank 1）を習得します。", nil, 0xc2e51e2e, nil, "um" },
  [653] = { "Seal of Might（Rank 1）を習得します。", nil, 0x61a215e5, nil, "um" },
  [655] = { "Blood Boil（Rank 2）を習得します。", nil, 0xc2e56137, nil, "um" },
