  [662] = { "Seal of Might（Rank 2）を習得します。", nil, 0x61a258ee, nil, "um" },
  [673] = { "$D1の間、アーマーを$N1増加させます。", "アーマーが$N1増加しています。", 0x92291afa, 0x97d97089, "uu" },
  [674] = { "片手武器・オフハンド用武器を、\n利き手でない方の手に装備\nできるようになります。", nil, 0x8a696461, nil, "um" },
  [676] = { "$D1の間、敵の武器を奪います。", "武装解除されています！", 0xef69889f, 0x98985ecd, "uu" },
  [678] = { "武器ダメージの$N1%に加え、さらに$N2のHolyダメージを与える瞬時の一撃です。", nil, 0xc64d407b, nil, "um" },
  [679] = { "武器ダメージの$N1%に加え、さらに$N2のHolyダメージを与える瞬時の一撃です。", nil, 0xc64d407b, nil, "um" },
  [680] = { "武器ダメージの$N1%に加え、さらに$N2のHolyダメージを与える瞬時の一撃です。", nil, 0xc64d407b, nil, "um" },
  [686] = { "対象にShadow属性の$N1ダメージを与えます。", nil, 0xc6f8d47d, nil, "um" },
  [687] = { "$D2の間、術者を守り、アーマーを$N1増加させ、体力回復量を5秒ごとに$N2増加させます。", "アーマーが$N1増加し、体力の回復量が5秒ごとに$N2増加します。", 0xb698fcaa, 0xd002df12, "uu" },
  [688] = { "ウォーロックの指揮下にあるImpを召喚します。", nil, 0xe09ab690, nil, "um" },
  [689] = { "$N2秒ごとに対象の体力を$N1吸い取り、術者に移します。効果時間は$D1です。", "$N2秒ごとに体力を$N1吸い取られ、術者に渡ります。", 0xc595b3f3, 0x66d948fc, "uu" },
  [691] = { "ウォーロックの指揮下にあるFelhunterを召喚します。", nil, 0xa4f630d4, nil, "um" },
  [693] = { "Minor Soulstoneを作成します。Soulstoneには対象1人の魂を保存できます。魂が保存されている間に対象が死亡すると、体力が$N1、マナが$N2の状態で復活できます。\n\nログアウトしてから15分以上経つと、創造されたアイテムは消えます。", nil, 0x2d3cf636, nil, "um" },
  [694] = { "$N1のダメージと中程度の脅威を与え、$D1の間、対象の攻撃を自分に集中させる挑発的な攻撃です。", "挑発されています。", 0x8506dcc4, 0x36f56123, "uu" },
  [695] = { "敵に影の矢を放ち、$N1のShadowダメージを与えます。", nil, 0xc6f8d47d, nil, "um" },
  [696] = { "$D2の間、術者を守り、アーマーを$N1増加させ、体力回復量を5秒ごとに$N2増加させます。", "アーマーが$N1増加し、体力の回復量が5秒ごとに$N2増加します。", 0xb698fcaa, 0xd002df12, "uu" },
  [697] = { "ウォーロックの指揮下にあるVoidwalkerを召喚します。", nil, 0xe766a608, nil, "um" },
  [698] = { "対象のグループメンバーを召喚する儀式を始めます。儀式を完了するには、術者と追加で2人のパーティーメンバーが必要です。参加するには、全員が戦闘状態でなく、ポータルを右クリックし、儀式が完了するまで動かないでいる必要があります。", nil, 0x243b7c43, nil, "um" },
  [699] = { "$N2秒ごとに対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "$N2秒ごとに体力を$N1吸い取られ、術者に渡ります。", 0xc595b3f3, 0x66d948fc, "uu" },
  [700] = { "敵の対象を最大$D1の間眠らせます。ダメージを受けると対象は目を覚まします。同時に眠らせておける対象は1体だけです。", "眠っています。", 0x26124111, 0x5339954e, "uu" },
  [702] = { "$D1の間、対象が与える物理ダメージを$N1減少させます。1体の対象に対して、各ウォーロックがかけられるCurseは1つだけです。", "与える物理ダメージが$N1減少しています。", 0x45b27a1b, 0x212710bf, "uu" },
  [703] = { "敵の首を絞め、$D1かけて$N1のダメージを与えます。ダメージはAttack Powerによって増加します。隠密状態で対象の背後にいる必要があります。コンボポイントを$N3獲得します。", "$N2秒ごとに$N1のダメージを受けます。", 0xdd3a1872, 0xef5a123f, "uu" },
  [704] = { "対象に無謀の呪いをかけ、$D1の間、対象のアーマーを$N1減少させます。呪われた敵は逃走せず、FearとHorrorの効果を無視します。1体の対象に対して、各ウォーロックがかけられるCurseは1つだけです。", "アーマーが$N1低下します。対象は逃走せず、FearとHorrorの効果を受けません。", 0x543f2e0b, 0x7af54e1d, "uu" },
  [705] = { "敵に影の矢を放ち、$N1のShadowダメージを与えます。", nil, 0xc6f8d47d, nil, "um" },
  [706] = { "$D2の間、術者を守り、アーマーを$N1、Shadow耐性を$N2増加させ、体力回復量を5秒ごとに$N3増加させます。", "アーマーが$N1、Shadow耐性が$N2増加し、体力の回復量が5秒ごとに$N3増加します。", 0x6ab340ac, 0x91ee7074, "uu" },
  [707] = { "敵を焼き、$N1のFireダメージを与え、さらに$D1かけて$N2のFireダメージを与えます。", "$N2秒ごとに$N1のFireダメージを受けます。", 0xe3931f57, 0x0d35ca56, "uu" },
  [709] = { "$N2秒ごとに対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "$N2秒ごとに体力を$N1吸い取られ、術者に渡ります。", 0xc595b3f3, 0x66d948fc, "uu" },
  [710] = { "敵対象を追放し、最大$D1の間あらゆる行動を封じますが、その間は無敵になります。一度に追放できる対象は一体だけです。DemonsとElementalsにのみ有効です。", "無敵ですが、行動できません。", 0x655db914, 0xb1a1673e, "uu" },
  [712] = { "ウォーロックの指揮下にあるSuccubusを召喚します。", nil, 0x7284109d, nil, "um" },
  [713] = { "ウォーロックの指揮下にあるIncubusを召喚します。", nil, 0x76bdb1f3, nil, "um" },
  [724] = { "プリーストの近くに聖なるLightwellを作り出します。レイドまたはパーティのメンバーはLightwellをクリックすると、$D1かけて体力を$N1回復できます。攻撃を受けると効果は解除されます。Lightwellは$D2の間、または5回のチャージを使い切るまで持続します。", nil, 0x3bb13606, nil, "um" },
  [740] = { "$N1ヤード以内にいる近くのすべてのパーティメンバーを、$D2の間、$D1ごとに$N2回復させます。ドルイドは呪文を維持するためにチャネリングを続ける必要があります。", "$N2秒ごとに近くのパーティメンバーを$N1回復します。", 0x96808906, 0x80aae398, "uu" },
  [746] = { "$D1かけて$N1のダメージを回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0xcb31688f, 0x4b6eb5c1, "uu" },
  [750] = { "Plateが装備可能になる", nil, 0x487d14a3, nil, "um" },
  [755] = { "術者がチャネリングしている間、$D1にわたって術者のペットに体力を毎秒$N1与えます。発生する脅威は少なくなります。", { "Lifeを転送中。脅威の生成量が$N1%増加しています。", "Lifeを転送中。", shape = { "1/0", "0/0" } }, 0x0aeefa60, 0xe55a3f4d, "uu" },
  [758] = { "武器にFireの力を宿し、呪文のクリティカル率を$N1%、Fire呪文によるダメージを最大$N2増加させます。", nil, 0x97c5eef5, nil, "um" },
  [759] = { "使用すると即座にマナを$N1回復できるmana agateを創造します。\n\nログアウトしてから15分以上経つと、創造されたアイテムは消えます。", nil, 0xf55fa5a2, nil, "um" },
  [766] = { "Water Elemental（Rank 1）を習得します。", nil, 0x68723cab, nil, "um" },
  [768] = { "猫の姿に変身し、近接攻撃力を敏捷性に加えて$N1上昇させます。また、術者をPolymorph効果から守り、さまざまな猫の能力を使えるようにします。\n\n変身することで、術者はPolymorphとMovement Impairing効果から解放されます。", "Polymorphの効果が効きません。近接攻撃力が$N1と敏捷性分増加します。", 0x7f918215, 0x0923d6b6, "uu" },
  [769] = { "近くの敵$N1体をなぎ払い、$N2のダメージを与えます。", nil, 0xb0c704b4, nil, "um" },
  [770] = { "$D1の間、対象のアーマーを$N1減少させます。効果中、対象はステルスや透明化ができません。", "アーマーが$N1低下します。ステルスも透明化もできません。", 0xf183631b, 0xa06fedc8, "uu" },
  [772] = { "対象を傷つけて出血させ、$D1かけて$N1のダメージを与えます。", "出血しており、$N2秒ごとに$N1のダメージを受けます。", 0x47f171f5, 0xbabe73bb, "uu" },
  [774] = { "$D1かけて対象を$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x3367b9a9, 0x1302c045, "uu" },
  [776] = { "味方の対象にかかっている魔法をすべて消し去り、$D1の間、対象がいかなる魔法の影響も受けないようにします。", nil, 0x1df7d58d, nil, "um" },
  [778] = { "$D1の間、対象のアーマーを$N1減少させます。効果中、対象はステルスや透明化ができません。", "アーマーが$N1低下します。ステルスも透明化もできません。", 0xf183631b, 0xa06fedc8, "uu" },
  [779] = { "近くの敵$N1体をなぎ払い、$N2のダメージを与えます。", nil, 0xb0c704b4, nil, "um" },
  [780] = { "近くの敵$N1体をなぎ払い、$N2のダメージを与えます。", nil, 0xb0c704b4, nil, "um" },
  [781] = { "脅威を下げることでターゲットからの離脱を試みます。\n自動攻撃を停止します。", nil, 0x30340e84, nil, "um" },
  [782] = { "味方の対象から棘が生え、攻撃してきた相手に$N1のNatureダメージを与えます。効果時間は$D1です。", "攻撃者に$N1のNatureダメージを与えます。", 0x0eddc25a, 0x763a853a, "uu" },
  [783] = { "ドルイドを旅の姿に変え、移動速度を$N1%上昇させます。また、術者をPolymorph効果から守ります。屋外でのみ使用できます。\n\n変身することで、術者はPolymorphとMovement Impairing効果から解放されます。", "Polymorphの効果が効きません。移動速度が$N1%増加します。", 0x024780e7, 0x71489b20, "uu" },
  [789] = { "Divine Escape（Rank 1）を習得します。", nil, 0x97675ca1, nil, "um" },
  [806] = { "$D2の間、筋力が$N1増加し、$N3秒ごとに自分が$N2のダメージを受けます。", "筋力と持続ダメージが増加しています。", 0x64c15adc, 0x9c65d114, "uu" },
  [818] = { "キャンプファイヤーを作り、近くに\nいると精神を4増加の効果と、\ncooking(料理)ができるようになります。", nil, 0x0e71d154, nil, "um" },
  [822] = { "Arcane属性のダメージを1%減らす", nil, 0xb89cda49, nil, "um" },
  [833] = { "即座に$N1のダメージを回復します。さらに$D1かけてマナを$N2回復します。飲んでいる間は座っている必要があります。", "毎秒マナを$N1回復します。", 0xfd4248b6, 0x66fae081, "uu" },
  [834] = { "$D1の間、アーマーを$N1増加させます。", "アーマーが$N1増加しています。", 0x92291afa, 0x97d97089, "uu" },
  [835] = { "対象を$D1スタンさせます。Nagaは$D2の間Stunned状態になり、クールダウンの$N3%が返還されます。", "スタンしています。", 0x9a8cedc4, 0x27f95286, "uu" },
  [837] = { "敵に冷気の矢を放ち、$N1のFrostダメージを与え、$D1の間移動速度を$N2%低下させます。", "移動速度が$N1%低下しています。", 0x0ea2143b, 0xbe1d3d24, "uu" },
  [842] = { "Ethereal Form（Rank 2）を習得します。", nil, 0x9c857b11, nil, "um" },
  [845] = { "対象と近くにいるもう一体の敵に、武器ダメージに加えて$N1のダメージを与えるなぎ払い攻撃です。", nil, 0xdd419f36, nil, "um" },
  [851] = { "最大$D1の間、敵を無力な羊に変え、呪文の詠唱も攻撃もできなくし、移動速度を$N1%低下させます。", "詠唱も攻撃も呪文の使用もできず、移動速度が$N1%低下しています。", 0xafa4f8cd, 0xa5ab0eb3, "uu" },
  [853] = { "対象を$D1スタンさせます。", "スタンしています。", 0xb330d181, 0x27f95286, "uu" },
  [857] = { "宝箱などの鍵のかかった物を魔法で開けます。", nil, 0xc00c5949, nil, "um" },
  [864] = { "Seal of Righteousness（Rank 1）を習得します。", nil, 0x2ad909be, nil, "um" },
  [865] = { "術者の近くの敵に$N1のFrostダメージを与え、最大$D1の間その場に凍りつかせます。ダメージを与えると効果が解けることがあります。", "凍りついてその場から動けません。", 0x65ba8ef1, 0xe9c46551, "uu" },
